// ASK 371 word match (W4 proposal, accepted W1 7799 item 5): ASK 366 FOLD, then irregular KJV table, then suffix strip; fixed stop list.
const FOLD=x=>String(x==null?'':x).replace(/[‘’ʼ´`]/g,"'").replace(/\[[^\]\n]*:[^\]\n]*\]/g,' ').replace(/[\[\]]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const IRR={took:'take',taken:'take',taking:'take',takes:'take',found:'find',finding:'find',knew:'know',known:'know',knowing:'know',knoweth:'know',came:'come',coming:'come',cometh:'come',begat:'beget',begotten:'beget',begetteth:'beget',bare:'bear',born:'bear',borne:'bear',beareth:'bear',gave:'give',given:'give',giveth:'give',giving:'give',spake:'speak',spoken:'speak',speaketh:'speak',made:'make',making:'make',maketh:'make',saw:'see',seen:'see',seeth:'see',went:'go',gone:'go',goeth:'go',said:'say',saith:'say',saying:'say'};
const STOP=new Set('a an and the of to in into on unto upon out up at by for from with without after before till until not no nor or but if that this these those which who whom whose what when where while as so then than there here also all any every each such own same is are was were be been being am art shall will would should may might must can could do did does doth hath have has had his her hers him he she it its they them their thee thou thy thine ye you your my me mine i we us our s'.split(' '));
const stem=w=>{if(IRR[w])return IRR[w];for(const sf of ['eth','est','ing','ed','es','en','s']){if(w.length>sf.length+2&&w.endsWith(sf))return w.slice(0,-sf.length).replace(/(.)\1$/,'$1').replace(/e$/,'');}return w.replace(/e$/,'');};
const content=t=>{const m=new Map();for(const w of FOLD(t).split(' ')){if(!w||STOP.has(w)||/^\d+$/.test(w))continue;const s=stem(w);if(!m.has(s))m.set(s,w);}return m;};
const TOPIC=new Set(['god','son','christ','lord','jesus','holy','ghost'].map(stem));
// rev 4 (W1 7799): a CARRIED BY passes when one content word of its row words also stands in the answer's ANSWER or FAILS words and NOT in the pressed MEANS words
// rev 5 (W1 7805, option b): the shared word must not be a topic word; a carry that shares only topic words is refused (they are still reported)
// REF (W2 7806 item 2, NOT RULED): a carry also passes when the answer words name the carry's own reference
function carry(cb,ans,means,opt){opt=opt||{};const C=content(cb),A=content(ans),M=content(means);const shared=[...C.keys()].filter(s=>A.has(s)&&!M.has(s));const real=shared.filter(s=>!TOPIC.has(s));
 const refHit=!!(opt.ref&&opt.ref.c&&new RegExp('\\b'+opt.ref.book.replace(/\s+/g,'\\s+')+'\\.?\\s+'+opt.ref.c+'\\s*:\\s*'+opt.ref.v+'(?![0-9])').test(String(ans)));
 return {pass:real.length>0||refHit,byRef:!real.length&&refHit,shared:real.map(s=>C.get(s)+'/'+A.get(s)),topic:shared.filter(s=>TOPIC.has(s)).map(s=>C.get(s))};}
module.exports={FOLD,stem,content,carry,STOP,IRR,TOPIC};
